using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Configuration ──────────────────────────────────────────────────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var model  = Environment.GetEnvironmentVariable("OPENAI_MODEL")  ?? "gpt-4o-mini";

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Set the OPENAI_API_KEY environment variable and try again.");
    return 1;
}

// ── Chat client with automatic function invocation ─────────────────────────────
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// ── Tools ──────────────────────────────────────────────────────────────────────
var notebook = new Notebook();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch.SearchAsync,  name: "search_web",  description: "Search the web and return result snippets."),
        AIFunctionFactory.Create(notebook.TakeNote,      name: "take_note",   description: "Save a research note for later reference."),
        AIFunctionFactory.Create(notebook.ReadNotes,     name: "read_notes",  description: "Retrieve all saved research notes."),
    ]
};

// ── Prompt ──────────────────────────────────────────────────────────────────────
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided.");
    return 1;
}

Console.WriteLine($"\n🔬 Researching \"{topic}\" …\n");

List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Follow these steps:
        1. Search the web 2-3 times with varied queries to cover the topic broadly.
        2. After each search, use take_note to record the key findings.
        3. When done searching, call read_notes to review everything.
        4. Finally, write a well-structured summary with sections and citations.
        """),
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary:\n{topic}")
];

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n════════════════════════════════════════");
Console.WriteLine("📋  RESEARCH SUMMARY");
Console.WriteLine("════════════════════════════════════════\n");
Console.WriteLine(response);
return 0;

