/// <summary>Web search tool – fetches real results from DuckDuckGo Lite (no API key needed).</summary>
static class WebSearch
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍  Searching: \"{query}\"");

        try
        {
            // DuckDuckGo HTML lite – free, no key required.
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.Add("User-Agent", "ResearchAgent/1.0");

            var html = await Http.SendAsync(request);
            var body = await html.Content.ReadAsStringAsync();

            // Extract snippets from the result page.
            var snippets = ParseSnippets(body, maxResults: 5);

            if (snippets.Count == 0)
                return "No results found.";

            return JsonSerializer.Serialize(snippets, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    /// <summary>Lightweight HTML scraper for DuckDuckGo Lite result snippets.</summary>
    private static List<SearchResult> ParseSnippets(string html, int maxResults)
    {
        var results = new List<SearchResult>();
        var span = html.AsSpan();

        // Each result snippet lives inside <a class="result__snippet">…</a>
        // and each title inside <a class="result__a">…</a>.
        const string titleMarker   = "class=\"result__a\"";
        const string snippetMarker = "class=\"result__snippet\"";

        int pos = 0;
        while (results.Count < maxResults)
        {
            int titleIdx = html.IndexOf(titleMarker, pos, StringComparison.Ordinal);
            if (titleIdx < 0) break;

            var title = ExtractTagContent(html, titleIdx);
            int snippetIdx = html.IndexOf(snippetMarker, titleIdx, StringComparison.Ordinal);
            var snippet = snippetIdx >= 0 ? ExtractTagContent(html, snippetIdx) : "";

            if (!string.IsNullOrWhiteSpace(title))
                results.Add(new SearchResult(StripTags(title).Trim(), StripTags(snippet).Trim()));

            pos = Math.Max(titleIdx + 1, snippetIdx + 1);
        }

        return results;
    }

    private static string ExtractTagContent(string html, int markerPos)
    {
        int gt = html.IndexOf('>', markerPos);
        if (gt < 0) return "";
        int lt = html.IndexOf('<', gt);
        if (lt < 0) return "";
        // Content may span child tags; grab until the closing </a> or </td>.
        int end = html.IndexOf("</a>", gt, StringComparison.Ordinal);
        if (end < 0) end = html.IndexOf("</td>", gt, StringComparison.Ordinal);
        if (end < 0) end = lt;
        return html[(gt + 1)..end];
    }

    private static string StripTags(string s)
    {
        var clean = new System.Text.StringBuilder(s.Length);
        bool inside = false;
        foreach (char c in s)
        {
            if (c == '<') { inside = true; continue; }
            if (c == '>') { inside = false; continue; }
            if (!inside) clean.Append(c);
        }
        return WebUtility.HtmlDecode(clean.ToString());
    }

    private record SearchResult(string Title, string Snippet);
}

/// <summary>Note-taking tool – accumulates findings for the agent to review.</summary>
class Notebook
{
    private readonly List<string> _notes = [];

    public string TakeNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝  Note #{_notes.Count} saved");
        return $"Saved. You now have {_notes.Count} note(s).";
    }

    public string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  📖  Reading {_notes.Count} note(s)");
        return string.Join("\n\n---\n\n",
            _notes.Select((n, i) => $"### Note {i + 1}\n{n}"));
    }
}

